def fibonacci(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# Calculate F_k for k=2 up to k=15
F = {}
for k in range(2, 16):
    F[k] = fibonacci(k)

print("Fibonacci numbers F_k for k=2 to k=15:")
for k in range(2, 16):
    print(f"F_{k} = {F[k]}")

# The required differences are D = {F_2, F_3, ..., F_15}
required_differences = set(F.values())

# Construct the set S using the values of F_0 through F_15
# F_0 = 0, F_1 = 1, F_2 = 1
S_elements = set([0, 1])
for k in range(2, 16):
    S_elements.add(F[k])

S_list = sorted(list(S_elements))
print("\nConstructed set S (unique values of F_0 through F_15):")
print(S_list)
print(f"Size of S: {len(S_list)}")

